csui.define('dctmw/controls/signin/repository.list.view',[
  'nuc/lib/marionette',
  'dctmw/controls/signin/repository.view'
], function (Marionette, RepositoryItemView) {
  'use strict';

  var RepositoryListView = Marionette.CollectionView.extend({
    tagName: 'select',
    tabindex: '0',
    childView: RepositoryItemView,
    className: 'repository-select',
    attributes: { "aria-label": "Select a repository", "required": "required" },

    getRepositoryById: function (id) {
      var repository;
      this.collection.models.some(function (model) {
        model = model.has('repository') ? model.get('repository') : model;
        if (model.id === id) {
          repository = model;
          return true;
        }
      });
      return repository;
    },

    // Returns an index between 1 and the collection length if id is found, 0 if not found
    getRepositoryIndex: function (id) {
      var result = 0;
      var index = 1;
      this.collection.models.some(function (model) {
        var modelRepo = model.get('repository');
        if (modelRepo.id === id) {
          result = index;
          return true;
        }
        index += 1;
      });
      return result;
    }
  });

  return RepositoryListView;
});
