csui.define('dctmw/server.adaptors/models/nuc/member.mixin',[
  'nuc/lib/underscore',
  'nuc/utils/url',
  'dctmw/server.adaptors/converters/user',
  'dctmw/utils/rest.linkrels',
  'dctmw/utils/rest.resources'
], function (_, Url, userConverter, RestLinkrels, RestResources) {
  'use strict';

  return {

    mixin: function (prototype) {

      return _.extend(prototype, {

        makeServerAdaptor: function (/*options*/) {
          return this;
        },

        url: function () {
          var currRepoLinks = RestResources.getCurrentRepository().get('links');
          return Url.combine(RestLinkrels.getLink(currRepoLinks, RestLinkrels.SELF), 'users', this.get('id'));
        },

        parse: function (response) {
          return userConverter.convertUser(response);
        }

      });

    }

  };

});
