import {Model} from 'nuc/lib/backbone';
import OTWCElementView from 'dctmw/controls/otwc/otwc.element.view';

class OTWCButtonView extends OTWCElementView {
  tagName() {
    return 'otc-button';
  }
  
  triggers() {
    return {
      click: 'click'
    };
  }
  
  constructor (options={}) {
    options.model = options.model instanceof Model ? options.model : new Model({attr_type: 'secondary'});
    super(options);
  }
  onRender(){
    super.onRender();

    //When this line was added, in chrome browser, when the otc-button is attached to dom with disabled state,
    // and enabled later, the accessiblity tree still had disabled as true. So with windows narrator, the enter/space key event was not 
    // received by the otc-button.  [DTWO-113567]
    this.$el.addClass('dctm-binf-hidden');
    setTimeout(() => this.$el.removeClass('dctm-binf-hidden'));
  }
}

Object.defineProperty(OTWCButtonView.prototype.constructor, 'name', {value: 'OTWCButtonView'});
export default OTWCButtonView;