csui.define('dctmw/controls/signin/application.view',[
  'nuc/lib/marionette'
], function (Marionette) {
  'use strict';

  var ApplicationItemView = Marionette.ItemView.extend({
    tagName: 'option',
    className: 'signin-option',

    template: false,
    onRender: function () {
      var name = this.model.get('applicationName'),
        label = this.model.get('applicationLabel');
      this.$el.text(label || name);
      this.$el.val(name);
    }
  });

  return ApplicationItemView;
});