import module from 'module';
import _ from 'nuc/lib/underscore';
import ToolItemMask from 'csui/controls/toolbar/toolitems.mask';
import GlobalMenuItemsMask from 'csui/utils/toolitem.masks/global.toolitems.mask';
import toolbarItems from 'dctmw/controls/table/toolbaritems';

class ToolbarItemsMasks extends Object{
  constructor(options={}) {
    super(options);
    
    this.options = options;
    this._initialize(options);
    this._initializeMasks();
    this._evaluateAndApplyMask();
  }
  
  _initialize(/*options*/) {
    //Usecase specific code that needs to execute before _initializeMasks
  }
  
  _initializeMasks() {
    const toolbars = _.keys(this.options.toolbarItems ?? toolbarItems),
      config = this.options.config ?? module.config();
    
    this.toolbars = _.reduce(toolbars, function (toolbars, toolbar) {
      const mask = new ToolItemMask(new GlobalMenuItemsMask(), {normalize: false});
      // Masks passed in by separate require.config calls are sub-objects
      // stored in the outer object be different keys
      _.each(config, function (source/*, key*/) {
        source = source[toolbar];
        if (source) {
          mask.extendMask(source);
        }
      });
      // Enable restoring the mask to its initial state
      mask.storeMask();
      toolbars[toolbar] = mask;
      return toolbars;
    }, {});
    
    ToolbarItemsMasks.toolbars = toolbars;
  }
  
  _evaluateAndApplyMask() {
    //Usecase specific code to extendMask()/restoreMask() on this.toolbars items as applicable
  }
}

Object.defineProperty(ToolbarItemsMasks.prototype.constructor, 'name', {value: 'ToolbarItemsMasks'});
export default ToolbarItemsMasks;